import { MakeLogicType, connect, kea, key, listeners, path, props } from 'kea'
import posthog from 'posthog-js'

import { SaveAsMenuItem } from 'scenes/data-warehouse/editor/editorSceneLogic'
import { sqlEditorLogic } from 'scenes/data-warehouse/editor/sqlEditorLogic'
import { SQLEditorMode } from 'scenes/data-warehouse/editor/sqlEditorModes'

export interface TracingSqlEditorTrackingLogicProps {
    sqlEditorTabId: string
}

const captureSaved = (target: SaveAsMenuItem['action']): void => {
    posthog.capture('tracing sql query saved', { target })
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface tracingSqlEditorTrackingLogicActions {
    sqlEditorRunQuery: (
        queryOverride?: string | undefined,
        switchTab?: boolean | undefined
    ) => {
        queryOverride: string | undefined
        switchTab: boolean | undefined
    } // sqlEditorLogic
    sqlEditorSaveAsEndpointSubmit: (
        name: string,
        description?: string | undefined,
        queryOverride?: string | undefined
    ) => {
        description: string | undefined
        name: string
        queryOverride: string | undefined
    } // sqlEditorLogic
    sqlEditorSaveAsInsightSubmit: (
        name: string,
        queryOverride?: string | undefined
    ) => {
        name: string
        queryOverride: string | undefined
    } // sqlEditorLogic
    sqlEditorSaveAsViewSubmit: (
        name: string,
        materializeAfterSave?: any,
        fromDraft?: string | undefined,
        folderId?: string | null | undefined,
        isTest?: any,
        queryOverride?: string | undefined,
        incremental?: import('~/types').DataWarehouseSavedQueryIncremental | undefined
    ) => {
        folderId: string | null | undefined
        fromDraft: string | undefined
        incremental: import('~/types').DataWarehouseSavedQueryIncremental | undefined
        isTest: any
        materializeAfterSave: any
        name: string
        queryOverride: string | undefined
    } // sqlEditorLogic
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface tracingSqlEditorTrackingLogicMeta {
    key: string
}

export type tracingSqlEditorTrackingLogicType = MakeLogicType<
    {},
    tracingSqlEditorTrackingLogicActions,
    TracingSqlEditorTrackingLogicProps,
    tracingSqlEditorTrackingLogicMeta
>

export const tracingSqlEditorTrackingLogic = kea<tracingSqlEditorTrackingLogicType>([
    path(['products', 'tracing', 'frontend', 'components', 'TracingSqlEditor', 'tracingSqlEditorTrackingLogic']),
    props({} as TracingSqlEditorTrackingLogicProps),
    key((props) => props.sqlEditorTabId),
    connect((props: TracingSqlEditorTrackingLogicProps) => ({
        actions: [
            sqlEditorLogic({ tabId: props.sqlEditorTabId, mode: SQLEditorMode.Embedded }),
            [
                'runQuery as sqlEditorRunQuery',
                'saveAsViewSubmit as sqlEditorSaveAsViewSubmit',
                'saveAsInsightSubmit as sqlEditorSaveAsInsightSubmit',
                'saveAsEndpointSubmit as sqlEditorSaveAsEndpointSubmit',
            ],
        ],
    })),
    listeners(({ cache }) => ({
        sqlEditorRunQuery: () => {
            // Skips the editor's auto-run with the default query on first mount.
            if (!cache.firstRunSeen) {
                cache.firstRunSeen = true
                return
            }
            posthog.capture('tracing sql query run')
        },
        sqlEditorSaveAsViewSubmit: () => captureSaved('view'),
        sqlEditorSaveAsInsightSubmit: () => captureSaved('insight'),
        sqlEditorSaveAsEndpointSubmit: () => captureSaved('endpoint'),
    })),
])
